{"results":[{"id":"R1","verdict":"partial","reason":"safeClient's Dialer.Control blocks loopback/private/link-local/unspecified IPs at connect time (so also after redirects), but the diff never shows the delivery worker using safeClient().","quotes":[{"path":"internal/delivery/client.go","line":10,"text":"if ip == nil || ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsUnspecified() {"},{"path":"internal/delivery/client.go","line":11,"text":"return fmt.Errorf("refusing to connect to %s", ip)"}],"missing":"Proof the delivery worker performs requests via safeClient() instead of http.DefaultClient; also block link-local multicast/metadata ranges and limit redirects.","suggestion":{"summary":"Wire safeClient into the delivery worker and test the metadata attack","code":"// internal/delivery/worker.go
var deliveryHTTP = safeClient()

func (w *Worker) deliver(ctx context.Context, hook Webhook, body []byte) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, hook.URL, bytes.NewReader(body))
	if err != nil {
		return err
	}
	resp, err := deliveryHTTP.Do(req) // was http.DefaultClient.Do
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	return nil
}

// internal/delivery/worker_test.go
func TestDeliveryRefusesMetadataEndpoint(t *testing.T) {
	err := (&Worker{}).deliver(context.Background(),
		Webhook{URL: "http://169.254.169.254/latest/meta-data/"}, []byte("{}"))
	if err == nil || !strings.Contains(err.Error(), "refusing to connect") {
		t.Fatalf("expected SSRF refusal, got %v", err)
	}
}"}}]}
